argv:
query=query($owner: String!, $repo: String!, $b0: String!) {
  repository(owner: $owner, name: $repo) {
    branchProtectionRules(first: 20) { nodes { pattern requiredStatusChecks { context } } }
    b0: pullRequests(headRefName: $b0, first: 1, orderBy: {field: CREATED_AT, direction: DESC}) { nodes { ...prStatus } }
  }
}
fragment prStatus on PullRequest { number url body isDraft baseRefName headRefOid mergeable mergeStateStatus reviewDecision state mergedAt timelineItems(last: 1, itemTypes: [CLOSED_EVENT]) { nodes { ... on ClosedEvent { actor { login } } } } files(first: 1) { totalCount } labels(first: 20) { nodes { name } } latestOpinionatedReviews(first: 20) { nodes { state author { login __typename } commit { oid } } } history: commits(last: 50) { nodes { commit { oid committedDate messageHeadline } } } checks: commits(last: 1) { nodes { commit { statusCheckRollup { state contexts(first: 100) { nodes { __typename ... on CheckRun { name conclusion status } ... on StatusContext { context state } } } } } } } events: timelineItems(last: 100, itemTypes: [LABELED_EVENT, UNLABELED_EVENT, HEAD_REF_FORCE_PUSHED_EVENT]) { nodes { __typename ... on LabeledEvent { createdAt label { name } actor { login } } ... on UnlabeledEvent { createdAt label { name } actor { login } } ... on HeadRefForcePushedEvent { createdAt beforeCommit { oid } } } } comments(last: 40) { nodes { id author { login } } } }
